<?php declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';

/*
 * QA-3: every third-party library is served from this origin, listed in
 * assets/vendor/VENDOR.json (generated by tools/vendor.mjs) together with its
 * version, sha256 and sha384. Nothing is fetched from a CDN, so the page
 * cannot be broken or hijacked by one, and each tag carries an integrity hash
 * so a tampered file fails closed instead of executing.
 */
$vendorManifest = null;
$vendorPath = __DIR__ . '/assets/vendor/VENDOR.json';
if (is_readable($vendorPath)) {
    $decoded = json_decode((string)file_get_contents($vendorPath), true);
    if (is_array($decoded)) {
        $vendorManifest = $decoded;
    }
}

$asset = static function (string $relative): string {
    /* Cache-busting for our own files (QA-4): the build writes the hash into
     * the filename, so this is a straight path, but keep the helper in one
     * place for the dev build too. */
    return htmlspecialchars($relative, ENT_QUOTES);
};

function vendorTag(array $entry): string
{
    $integrity = isset($entry['integrity']) ? ' integrity="' . htmlspecialchars((string)$entry['integrity'], ENT_QUOTES) . '"' : '';
    if (($entry['tag'] ?? '') === 'script') {
        $defer = !empty($entry['defer']) ? ' defer' : '';
        return '  <script' . $defer . ' src="' . htmlspecialchars((string)$entry['src'], ENT_QUOTES) . '"' . $integrity . '></script>';
    }
    return '  <link rel="stylesheet" href="' . htmlspecialchars((string)$entry['href'], ENT_QUOTES) . '"' . $integrity . '>';
}
?><!doctype html>
<html lang="en" class="bg-slate-950">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>CallScope · Reporting</title>
  <!-- Tabulator (JS + CSS) is injected on first use by the call modal: see
       ensureTabulator() in assets/js/src/lib/react.js. It reads the same
       manifest through the #vendor-manifest element at the end of <body>. -->
  <link rel="stylesheet" href="<?= $asset('assets/css/app.css') ?>">
<?php if ($vendorManifest === null): ?>
  <!-- assets/vendor/VENDOR.json is missing: run `node tools/vendor.mjs`. The
       app cannot load React without it, so say so instead of rendering blank. -->
  <style>#root::before{content:"Vendored assets are missing — run node tools/vendor.mjs";display:block;padding:2rem;color:#f87171;font:14px/1.6 monospace}</style>
<?php else: ?>
<?php foreach (($vendorManifest['load'] ?? []) as $entry): ?>
<?= vendorTag($entry) ?>

<?php endforeach; ?>
<?php endif; ?>
</head>
<body class="min-h-screen bg-slate-950 text-slate-200 antialiased">
  <div id="root"></div>

  <script defer src="<?= $asset('assets/js/app.js') ?>"></script>
<?php if ($vendorManifest !== null): ?>
  <!-- Integrity for the lazily injected Tabulator files, kept in one place
       (the manifest) instead of hard-coded in the bundle. -->
  <script type="application/json" id="vendor-manifest"><?= json_encode($vendorManifest['lazy'] ?? new stdClass(), JSON_UNESCAPED_SLASHES) ?></script>
<?php endif; ?>
</body>
</html>
